CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,username VARCHAR(80) NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(50) NULL,entity_id INT UNSIGNED NULL,details TEXT NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(user_id),INDEX(action),INDEX(entity_type,entity_id),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
